INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (420, 1, 'PriorityClass 범위', 'PriorityClass 는 **어떤 범위** 의 오브젝트일까요?', '네임스페이스에 속할까요?', NULL, NULL, '[]', 'choice', '["특정 네임스페이스에만 속한다", "노드 하나에 속한다", "클러스터 범위", "Pod 하나에 속한다"]', 2, '쿠버네티스 문서는 PriorityClass 가 네임스페이스에 속하지 않는(non-namespaced) 오브젝트라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 2, 'value 범위', 'PriorityClass 의 **value** 로 쓸 수 있는 범위는 무엇일까요?', '32비트 정수이고 상한이 있어요.', NULL, NULL, '[]', 'choice', '["0 이상 100 이하의 정수", "32비트 정수, 10억 이하", "1 부터 10000 까지의 자연수", "제한이 없는 임의의 실수"]', 1, '문서는 value 가 32비트 정수이며 10억 이하이고 그보다 큰 값은 시스템 중요 Pod 용으로 예약되어 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 3, '이름 규칙', 'PriorityClass 의 **이름** 에 대한 규칙으로 맞는 것은 무엇일까요?', '시스템용 접두사가 막혀 있어요.', NULL, NULL, '[]', 'choice', '["system- 접두사를 쓸 수 없다", "system- 접두사를 반드시 붙여야 한다", "숫자로만 이루어져야 한다", "네임스페이스 이름과 같아야 한다"]', 0, '문서는 PriorityClass 이름이 DNS 서브도메인 이름이어야 하며 system- 접두사를 쓸 수 없다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 4, 'globalDefault', '`globalDefault: true` 인 PriorityClass 는 몇 개까지 둘 수 있을까요?', '기본값이 둘일 수는 없어요.', NULL, NULL, '[]', 'choice', '["네임스페이스마다 하나씩", "개수 제한 없이 여러 개", "노드마다 하나씩", "클러스터에 하나만"]', 3, '문서는 globalDefault 가 true 인 PriorityClass 는 한 클러스터에 하나만 존재할 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 5, '기본값의 적용 시점', 'globalDefault 클래스를 **추가** 하면 이미 실행 중인 Pod 의 우선순위는 어떻게 될까요?', '앞으로 만들 Pod 만 바뀌어요.', NULL, NULL, '[]', 'choice', '["모든 Pod 의 우선순위가 즉시 바뀐다", "모든 Pod 가 재시작되며 바뀐다", "이후 생성되는 Pod 에만 적용", "추가가 거부된다"]', 2, '문서는 globalDefault 클래스를 추가해도 기존 Pod 의 우선순위는 바뀌지 않고 추가 이후 생성되는 Pod 에만 적용된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 6, '기본 우선순위', 'globalDefault 클래스가 **없을 때** priorityClassName 이 없는 Pod 의 우선순위는 얼마일까요?', '0 이에요.', NULL, NULL, '[]', 'choice', '["1000", "0", "-1", "1000000000"]', 1, '문서는 globalDefault 로 지정된 클래스가 없으면 priorityClassName 이 없는 Pod 의 우선순위가 0 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 7, 'preemptionPolicy 기본', '`preemptionPolicy` 의 **기본값** 은 무엇일까요?', '낮은 Pod 를 선점해요.', NULL, NULL, '[]', 'choice', '["PreemptLowerPriority", "PreemptHigherPriority", "PreemptNever", "DisablePreempt"]', 0, '문서는 preemptionPolicy 의 기본값이 PreemptLowerPriority 이며 낮은 우선순위 Pod 를 선점할 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 8, 'Never 정책', '`preemptionPolicy: Never` 인 Pod 의 동작으로 맞는 것은 무엇일까요?', '비선점이에요.', NULL, NULL, '[]', 'choice', '["다른 Pod 를 선점하고 자신은 절대 선점당하지 않는다", "우선순위 큐에서 가장 뒤로 밀린다", "스케줄링 대상에서 제외된다", "큐에서 앞서지만 다른 Pod 를 선점하지 않는다"]', 3, '문서는 Never 가 비선점 방식으로 낮은 우선순위 Pod 보다 앞서지만 다른 Pod 를 선점하지 않으며 더 높은 우선순위의 Pod 에 의해서는 선점될 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 9, '없는 클래스', 'Pod 의 `priorityClassName` 이 **존재하지 않는** PriorityClass 이면 어떻게 될까요?', 'admission 단계에서 확인해요.', NULL, NULL, '[]', 'choice', '["우선순위 0 으로 생성된다", "가장 높은 우선순위로 생성된다", "Pod 가 거부된다", "클래스가 자동으로 만들어진다"]', 2, '문서는 우선순위 admission controller 가 priorityClassName 을 확인해 정수 값을 채우며 해당 PriorityClass 가 없으면 Pod 이 거부된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Pod 우선순위와 선점", "url": "https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/"}]'),
  (420, 10, '우선순위 지정', 'Pod 스펙에서 PriorityClass 를 가리키는 필드입니다. 빈칸을 채우세요.', '클래스 이름을 적어요.', NULL, NULL, '[]', 'fill', '["priorityClassName", "priority", "priorityName", "preemptionPolicy"]', NULL, 'Pod 스펙의 priorityClassName 에 PriorityClass 이름을 지정하면 admission controller 가 정수 값을 채웁니다.', '[0]', 'spec:
